import{calculator,CalcError,has,nonneg,dflt,bool}from './core.js?ver=01421f720c';import{bill_total}from './bill.js?ver=01421f720c';import{ac_units,home_load}from './load.js?ver=01421f720c';
export const ac_bill_impact=calculator((i,d)=>{const ac=ac_units.raw(i,d);const other_units=nonneg(i,'other_units');const was_protected=bool(i.protected);const limit=dflt(d,'protected_max_units');if(was_protected&&other_units>limit)throw new CalcError(`protected_max_${limit}_units`,'other_units');const total_units=other_units+ac.monthly_units;const protected_lost=was_protected&&total_units>limit;const addons={};for(const k of['sanctioned_kw','period','fc_surcharge_per_unit','qta_per_unit','fpa_per_unit','gst_pct'])if(has(i,k))addons[k]=i[k];const bill=(units,prot)=>bill_total.raw({...addons,units,protected:prot},d);const before=bill(other_units,was_protected);const after=bill(total_units,was_protected&&!protected_lost);const extra_rs=Math.max(0,after.total_rs-before.total_rs);const lock_months=protected_lost?dflt(d,'protected_months'):0;const lock_per_month=protected_lost?Math.max(0,bill(other_units,false).total_rs-before.total_rs):0;const lock_extra_rs=lock_months*lock_per_month;return{ac_name:ac.ac_name??'Custom AC',...(ac.ac_rated_w?{ac_rated_w:ac.ac_rated_w}:{}),avg_kw:ac.avg_kw,hours:ac.hours,days:ac.days,daily_units:ac.daily_units,ac_units:ac.monthly_units,other_units,total_units,sanctioned_kw:after.sanctioned_kw,before_rs:before.total_rs,after_rs:after.total_rs,extra_rs,rs_per_ac_unit:ac.monthly_units>0?extra_rs/ac.monthly_units:0,before_rate:before.rate,after_rate:after.rate,before_category:before.category,after_category:after.category,slab_jump:after.band_index>before.band_index||after.category !==before.category,protected_lost,protected_limit:limit,lock_months,lock_per_month,lock_extra_rs,ac_above_sanctioned:(ac.ac_rated_w??ac.avg_kw*1000)/1000>after.sanctioned_kw,};});
export const home_load_bill=calculator((i,d)=>{const out=home_load.raw(i,d);const b=bill_total.raw({units:out.monthly_units,sanctioned_kw:i.sanctioned_kw,protected:false},d);return{...out,bill_kw:b.sanctioned_kw,bill_rate:b.rate,bill_energy_rs:b.energy_rs,monthly_rs:b.total_rs};});
